const WEAR_SLOT = { head: 'HEAD', chest: 'CHEST', legs: 'LEGS', feet: 'FEET' }
const WEAR_SOUND = { head: 'item.armor.equip_leather', chest: 'item.armor.equip_leather', legs: 'item.armor.equip_leather', feet: 'item.armor.equip_leather' }
const WEAR_TIP = { warm: 'Warm: holds body heat in the cold.', cool: 'Cool: shades the body from sun and heat.', dry: 'Dry: keeps rain and water off the skin.' }

// Rhino: const inside a loop keeps its first value, so these are let.
StartupEvents.registry('item', event => {
  let Equippable = Java.loadClass('net.minecraft.world.item.equipment.Equippable')
  let EquipmentSlot = Java.loadClass('net.minecraft.world.entity.EquipmentSlot')
  let ResourceKey = Java.loadClass('net.minecraft.resources.ResourceKey')
  let EquipmentAssets = Java.loadClass('net.minecraft.world.item.equipment.EquipmentAssets')
  let Identifier = Java.loadClass('net.minecraft.resources.Identifier')
  Object.keys(DIAITHIR_WEAR).forEach(id => {
    let w = DIAITHIR_WEAR[id]
    let wear = Equippable.builder(EquipmentSlot[WEAR_SLOT[w[0]]])
      .setAsset(ResourceKey.create(EquipmentAssets.ROOT_ID, Identifier.parse('diaithir:' + id))).build()
    let b = event.create('diaithir:' + id).displayName(w[1]).unstackable().texture('diaithir:item/clothing/' + id)
      .component('minecraft:equippable', wear)
      .tooltip(Text.gray(w[2]))
    w[3].split(',').forEach(c => b.tooltip(Text.gray(WEAR_TIP[c])))
  })
})
